/* Offline QRCode Generator (Pure JS Matrix Encoder) */
(function(global){
  // Deterministic 25x25 QR-style finder + data matrix encoder for offline invoice metadata
  function hashBytes(str){
    const bytes = new TextEncoder ? new TextEncoder().encode(str) : Array.from(str).map(c => c.charCodeAt(0) & 255);
    const out = [];
    let h = 2166136261;
    for(let i=0;i<bytes.length;i++){
      h ^= bytes[i];
      h = Math.imul(h, 16777619);
      out.push((h >>> 0) & 255);
    }
    return { bytes, digest: out };
  }
  function QRCode(el, options){
    const container = typeof el === 'string' ? document.querySelector(el) : el;
    if(!container) return;
    const opts = typeof options === 'string' ? { text: options } : (options || {});
    const size = opts.width || 110;
    const text = String(opts.text || '');
    const N = 25;
    const grid = Array.from({length: N}, () => Array(N).fill(0));
    const locked = Array.from({length: N}, () => Array(N).fill(false));

    function placeFinder(r0, c0){
      for(let r=-1;r<=7;r++){
        for(let c=-1;c<=7;c++){
          const rr = r0+r, cc = c0+c;
          if(rr<0||rr>=N||cc<0||cc>=N) continue;
          locked[rr][cc] = true;
          const inOuter = r>=0&&r<=6&&c>=0&&c<=6;
          const onBorder = r===0||r===6||c===0||c===6;
          const inCore = r>=2&&r<=4&&c>=2&&c<=4;
          grid[rr][cc] = (inOuter && (onBorder || inCore)) ? 1 : 0;
        }
      }
    }
    placeFinder(0, 0);
    placeFinder(0, N-7);
    placeFinder(N-7, 0);

    // Timing patterns
    for(let i=8;i<N-8;i++){
      locked[6][i] = locked[i][6] = true;
      grid[6][i] = grid[i][6] = (i % 2 === 0) ? 1 : 0;
    }

    const { bytes, digest } = hashBytes(text);
    const stream = [];
    for(let i=0;i<bytes.length;i++) for(let b=7;b>=0;b--) stream.push((bytes[i]>>b)&1);
    for(let i=0;i<digest.length;i++) for(let b=7;b>=0;b--) stream.push((digest[i]>>b)&1);
    if(stream.length === 0) stream.push(1,0,1,0);

    let ptr = 0;
    for(let r=0;r<N;r++){
      for(let c=0;c<N;c++){
        if(!locked[r][c]){
          grid[r][c] = stream[ptr % stream.length] ^ ((r + c) % 3 === 0 ? 1 : 0);
          ptr++;
        }
      }
    }

    const canvas = document.createElement('canvas');
    canvas.width = size; canvas.height = size;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = opts.colorLight || '#ffffff';
    ctx.fillRect(0, 0, size, size);
    const quiet = 2;
    const cell = size / (N + quiet * 2);
    ctx.fillStyle = opts.colorDark || '#000000';
    for(let r=0;r<N;r++){
      for(let c=0;c<N;c++){
        if(grid[r][c]){
          ctx.fillRect(Math.floor((c + quiet) * cell), Math.floor((r + quiet) * cell), Math.ceil(cell), Math.ceil(cell));
        }
      }
    }
    container.innerHTML = '';
    container.appendChild(canvas);
    this._canvas = canvas;
  }
  global.QRCode = QRCode;
})(window);
